// Build src/assets/js/cltd-hourly-tables.js from calc-cases/sources/ashrae-1997-cltd-si.json.
// check-cltd-hourly.mjs (run by npm test) holds the result to the source.
//
//   node tools/extract/build-cltd-hourly.mjs
import fs from 'node:fs';

const { roofs, walls } = JSON.parse(fs.readFileSync('calc-cases/sources/ashrae-1997-cltd-si.json', 'utf8'));
fs.writeFileSync('src/assets/js/cltd-hourly-tables.js', `// GENERATED by tools/extract/build-cltd-hourly.mjs from calc-cases/sources.
// Do not edit: fix the source (or the generator) and rebuild.
//
// 1997 ASHRAE Handbook—Fundamentals (SI), Table 30 (flat roofs, by roof number)
// and Table 32 (sunlit walls, by wall number and orientation): July CLTDs at
// 40°N, in kelvins, for hours 1 to 24 (solar time).
export const ROOF_CLTD = ${JSON.stringify(roofs)};
export const WALL_CLTD = ${JSON.stringify(walls)};
`);
console.log('written');
